def pair_candidates(grid,maxdx=6):
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    H,W=len(grid),min(map(len,grid)); cand=[]
    for i in range(H):
      for j in range(i+1,H):
       for dx in range(-maxdx,maxdx+1):
        shared=miss=extra=0; n=0
        for c in range(W):
         q=c+dx
         if 0<=q<W:
          n+=1; a=grid[i][c]!=bg; b=grid[j][q]!=bg
          if a and b:shared+=1
          elif a:miss+=1
          elif b:extra+=1
        if shared>=2 and ((miss>=1 and extra==0) or (extra>=1 and miss==0)):
         dire='lower' if miss else 'upper'
         cand.append((j-i,dx,dire,i,j,shared,miss,extra,n))
    return bg,cand
