from collections import Counter,defaultdict

def transform(grid):
    h=len(grid); w=len(grid[0]); out=[r[:] for r in grid]
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Find repeated horizontal row-patterns in separated bands. Align them by shifts,
    # then paint the missing foreground cells in the less-complete copy.
    nonuniform=sum(len(set(r))>1 for r in grid)
    if nonuniform>=4:
        cand=[]
        for i in range(h):
          for j in range(i+2,h):
           dy=j-i
           for dx in range(-8,9):
            shared=miss=extra=0
            for c in range(w):
             q=c+dx
             if 0<=q<w:
              a=grid[i][c]!=bg; b=grid[j][q]!=bg
              if a and b: shared+=1
              elif a: miss+=1
              elif b: extra+=1
            if shared>=2 and ((miss>0 and extra==0) or (extra>0 and miss==0)):
             dire='lower' if miss else 'upper'
             cand.append((dy,dx,dire,i,j,shared,miss,extra))
        groups=defaultdict(list)
        for x in cand: groups[x[:3]].append(x)
        viable=[(k,v) for k,v in groups.items() if len(v)>=2]
        if viable:
            # Use the repeated alignment shared by multiple rows, not incidental nearby rows.
            key, vals=max(viable,key=lambda kv:(len(kv[1]),sum(x[5] for x in kv[1]),-sum(x[6]+x[7] for x in kv[1])))
            dy,dx,dire=key
            for _,_,_,i,j,_,_,_ in vals:
             if dire=='lower':
              for c in range(w):
               q=c+dx
               if 0<=q<w and grid[i][c]!=bg and grid[j][q]==bg: out[j][q]=1
             else:
              for q in range(w):
               c=q-dx
               if 0<=c<w and grid[j][q]!=bg and grid[i][c]==bg: out[i][c]=1
            return out
    # In a simple two-run row, highlight the trailing run.
    for r,row in enumerate(grid):
      changes=[c for c in range(1,w) if row[c]!=row[c-1]]
      if len(changes)==1:
       k=changes[0]
       # Ignore rows that are only a one-cell transition within the dominant background?
       for c in range(k,w): out[r][c]=1
    return out

